import csv, re
from decimal import Decimal
from datetime import datetime

MONTHS = {m: i for i, m in enumerate(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], 1)}
MAP = {
    'taxi':'Travel','uber':'Travel','flight':'Travel',
    'hotel':'Lodging','airbnb':'Lodging',
    'lunch':'Meals','dinner':'Meals','coffee':'Meals',
    'saas':'Software','software':'Software','license':'Software',
    'books':'Learning','course':'Learning',
}

def parse_date(raw):
    raw = raw.strip()
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d %b %Y'):
        try:
            return datetime.strptime(raw, fmt).date()
        except ValueError:
            pass
    raise ValueError(raw)

def parse_cents(raw):
    s = raw.strip()
    s = re.sub(r'^(USD\s*)', '', s, flags=re.I)
    s = re.sub(r'(\s*USD)$', '', s, flags=re.I)
    s = s.replace('$','').replace(',','').strip()
    return int((Decimal(s) * 100).to_integral_value())

rows = []
seen = set()
with open('expenses.csv', newline='') as f:
    for r in csv.DictReader(f):
        rid = int(r['id'])
        if rid in seen:
            continue
        seen.add(rid)
        if r['status'].strip().lower() == 'void':
            continue
        d = parse_date(r['date'])
        if d.year != 2026 or d.month != 10:
            continue
        cat = MAP[r['category'].strip().lower()]
        cents = parse_cents(r['amount'])
        rows.append((rid, d, cat, cents))

from collections import defaultdict
sums = defaultdict(int)
counts = defaultdict(int)
for rid, d, cat, cents in rows:
    sums[cat] += cents
    counts[cat] += 1

for cat in sorted(sums, key=lambda c: (-sums[c], c)):
    print(f'{cat}: {counts[cat]} ${sums[cat]/100:,.2f}')
print('TOTAL', len(rows), f'${sum(sums.values())/100:,.2f}')
print('FLAGS')
for rid, d, cat, cents in sorted(rows):
    if cents > 50000:
        print(f'#{rid} ${cents/100:,.2f} {cat}')
PY", "description": "Compute October totals from CSV"}

